int rds_atomic_op_setup(struct rds_sock *rs, struct rds_message *rm, struct cmsghdr *cmsg)
{
    struct rds_atomic_args *args;
    struct rds_atomic_notifier *notifier;
    int ret = -EINVAL;

    if (cmsg->cmsg_len < CMSG_LEN(sizeof(*args)))
        return -EINVAL;

    if (rm->atomic_op.active)
        return -EALREADY;

    args = CMSG_DATA(cmsg);

    if (args->op_type >= RDS_ATOMIC_OP_MAX)
        return -EINVAL;

    switch (args->op_type) {
        case RDS_ATOMIC_OP_READ:
        case RDS_ATOMIC_OP_WRITE:
            if (args->sg_count < 1 || args->sg_count > RDS_ATOMIC_MAX_SG)
                return -EINVAL;
            break;
        default:
            return -EINVAL;
    }

    rm->atomic_op.sg = kmalloc_array(args->sg_count, sizeof(*rm->atomic_op.sg), GFP_KERNEL);
    if (!rm->atomic_op.sg)
        return -ENOMEM;

    rm->atomic_op.sg_count = args->sg_count;

    if (args->local_addr & (sizeof(u32) - 1)) {
        kfree(rm->atomic_op.sg);
        return -EINVAL;
    }

    rm->atomic_op.local_addr = args->local_addr;

    if (args->notify) {
        notifier = kzalloc(sizeof(*notifier), GFP_KERNEL);
        if (!notifier) {
            kfree(rm->atomic_op.sg);
            return -ENOMEM;
        }
        rm->atomic_op.notifier = notifier;
    }

    rm->atomic_op.remote_addr = args->remote_addr;
    rm->atomic_op.key = args->key;
    rm->atomic_op.op_type = args->op_type;
    rm->atomic_op.active = 1;

    return 0;
}
